const express = require('express');
const { InternalBillingClient } = require('@repo/billing-client');
const { authenticateJwt } = require('../middleware/auth');
const { prisma } = require('../db');

const app = express();
app.use(express.json());

const billingClient = new InternalBillingClient({
  baseUrl: process.env.INTERNAL_BILLING_SERVICE_URL,
  m2mToken: process.env.INTERNAL_SERVICE_M2M_SECRET
});

app.post('/api/workspaces/:workspaceId/payment-methods', authenticateJwt, async (req, res) => {
  const { workspaceId } = req.params;
  const { paymentMethodToken, setAsDefault } = req.body;

  // Verify that the authenticated user is an owner or admin of the workspace
  const membership = await prisma.workspaceMember.findFirst({
    where: {
      workspaceId,
      userId: req.user.id,
      role: { in: ['OWNER', 'BILLING_ADMIN'] }
    },
    include: { workspace: true }
  });

  if (!membership) {
    return res.status(403).json({ error: 'Access denied: insufficient workspace billing permissions' });
  }

  // Derive customerId strictly from the verified workspace record, never from client body
  const customerId = membership.workspace.stripeCustomerId;
  if (!customerId) {
    return res.status(400).json({ error: 'No billing profile associated with this workspace' });
  }

  try {
    const result = await billingClient.attachPaymentMethod({
      workspaceId,
      customerId,
      paymentMethodToken,
      setAsDefault: Boolean(setAsDefault)
    });

    res.status(201).json(result);
  } catch (err) {
    res.status(500).json({ error: 'Failed to configure payment method' });
  }
});

app.listen(8081);
